  ["shared.previewsamples.spot_a_wanted_player.3f246b"] = "Repérer un joueur recherché",
  ["shared.previewsamples.see_the_wanted_popup_portrait_nearby_highlight.04e33a"] = "Voir le popup recherché, le portrait, le surlignage à proximité et la pièce de plaque signalétique. Replay utilise vos préférences sonores.",
  ["shared.previewsamples.portraits_use_your_selected_player_or_your.6ec2ed"] = "Les portraits utilisent votre joueur sélectionné ou votre personnage comme exemple étiqueté. Cela ne place jamais une prime sur eux. Les alertes en direct proviennent des observations, y compris les cibles, les survols et les plaques signalétiques.",
  ["shared.previewsamples.wanted_board.b69f07"] = "Vouloir un bureau",
  ["shared.previewsamples.wanted_cards_and_full_posters.c0244c"] = "Cartes recherchées et affiches complètes",
  ["shared.previewsamples.click_the_wanted_card_or_view_bounty.b1ae32"] = "Cliquez sur la carte recherchée ou sur Afficher la prime pour inspecter chaque contributeur, ses conditions, son financement et son expiration. Actualiser démontre un bouton et un chargeur désactivés pendant que les récompenses d'échantillon arrivent.",
  ["shared.previewsamples.start_tracking_adds_a_target_to_my.e9b443"] = "Commencer le suivi ajoute une cible à Mes primes. Après un kill détecté, View report ouvre son statut. Les affiches mettent la cible et la récompense en premier, utilisent la largeur du parchemin pour les détails et défilent au besoin. Les portraits indisponibles sont étiquetés.",
  ["shared.previewsamples.create_terms.1ea507"] = "Créer & termes",
  ["shared.previewsamples.build_a_sample_bounty.01af6d"] = "Construire un échantillon de prime",
  ["shared.previewsamples.three_steps_target_reward_review_nothing_is.cc55e8"] = "Trois étapes: Cible, Récompense, Révision. Rien n'est sauvegardé jusqu'à la confirmation finale. Un kill avec n'importe quelle fin est la valeur par défaut.",
  ["shared.previewsamples.save_returns_to_the_tour_sharing_is.631c62"] = "Enregistrer les retours à la tournée. Le partage est facultatif. Le suivi privé peut utiliser zéro or; les récompenses partagées ont besoin d'un montant positif et d'une date d'expiration. Les finitions préférées nécessitent l'examen de l'affiche. Aucune récompense en direct n'est créée.",
  ["shared.previewsamples.use_gold_across_your_characters.423446"] = "Utilisez de l'or sur vos personnages",
  ["shared.previewsamples.see_a_sample_wallet_and_the_bag.2652f4"] = "Voir un exemple de portefeuille et le sac d'or tooltip. Essayez les deux commutateurs, puis saisissez une récompense supérieure au montant disponible dans Créer & conditions.",
  ["shared.previewsamples.account_tracking_is_on_by_default_requiring.faa230"] = "Le suivi des comptes est activé par défaut. L'exigence de suffisamment d'or est désactivée par défaut : une récompense de dépassement du budget avertit mais peut être créée. Les soldes sont étendus à ce royaume ou à Forever realmset. Alt Les soldes sont mis à jour lorsque vous vous connectez; les paiements et les transferts restent manuels.",
  ["shared.previewsamples.guild_approval.d5172b"] = "Approbation de la guilde",
  ["shared.previewsamples.submit_and_approve_a_guild_bounty.93c32d"] = "Soumettre et approuver une prime de guilde",
  ["shared.previewsamples.try_awaiting_approval_officer_approval_and_rejection.1aed32"] = "Essayez d'attendre l'approbation, l'approbation de l'agent et le rejet, puis inspectez la carte recherchée qui en résulte. Ces rôles sont disponibles dans le tour même sans guilde.",
  ["shared.previewsamples.approved_guild_rewards_can_show_a_new.36cbe4"] = "Les récompenses de guilde approuvées peuvent afficher une affiche NEW BOUNTY. Cela annonce une récompense, pas une observation. Partager une récompense avec les conseils de guilde et globaux ne crée pas une deuxième obligation de paiement. Sur Forever, les récompenses communautaires se synchronisent uniquement avec les membres de votre jeu de règles.",
  ["shared.previewsamples.shared_arrivals.7e4e7c"] = "Arrivées partagées",
  ["shared.previewsamples.a_bounty_matches_your_filters.542556"] = "A bounty correspond à vos filtres",
  ["shared.previewsamples.use_start_tracking_or_ignore_on_the.ac8ad1"] = "Utilisez Démarrer le suivi ou Ignorer sur l'affiche entrante. Essayez des exemples de paramètres d'alerte et d'états de financement. Cette cible n'a pas été repérée.",
  ["shared.previewsamples.the_notification_minimum_counts_rewards_with_current.7ea6f7"] = "Le minimum de notification compte les récompenses avec les rapports de fonds disponibles actuels. Les offres importées, obsolètes ou non financées restent distinctes. Le suivi ne promet pas d'or; ignorer réduit au silence la prime de la cible et les alertes d'observation.",
  ["shared.previewsamples.grow_a_bounty_s_pot.fc063b"] = "Cultivez un pot de bounty",
  ["shared.previewsamples.add_a_sample_contribution_review_the_original.3e1e7c"] = "Ajoutez un exemple de contribution, passez en revue les conditions de l'afficheur original et voyez la mise à jour de la récompense combinée.",
  ["shared.previewsamples.accepting_the_terms_means_the_original_poster.cb648e"] = "L'acceptation des conditions signifie que l'afficheur original décide si une réclamation est admissible. Les contributeurs doivent leurs montants au même chasseur accepté. L'or n'est pas détenu ou transféré par l'addon.",
  ["shared.previewsamples.share_import.d10b63"] = "Partager & importer",
  ["shared.previewsamples.copy_a_bounty_link_and_review_an.e6954f"] = "Copier un lien de récompense et examiner une importation",
  ["shared.previewsamples.sharing_outside_the_addon_is_optional_copy.b960a6"] = "Le partage en dehors de l'addon est facultatif. Copiez un lien de prime globale, de guilde ou privée, puis vérifiez un exemple d'importation.",
  ["shared.previewsamples.choose_select_link_to_copy_press_ctrl.75c0bf"] = "Choisissez Sélectionner le lien à copier, appuyez sur Ctrl+C et envoyez le lien de récompense. Le destinataire choisit Importer la prime. Le partage dans le chat est disponible pour les primes privées et de groupe. Discord canal ouvre la destination du tableau partagé séparément. Les liens de visite sont délibérément invalides en dehors de la visite.",
  ["shared.previewsamples.kills_reports.48e18a"] = "Kills & rapports",
  ["shared.previewsamples.detected_kills_create_reports_automatically.0ec7e1"] = "Les kills détectés créent automatiquement des rapports",
  ["shared.previewsamples.use_view_sample_report_to_follow_review.4dce46"] = "Utilisez Voir l'exemple de rapport pour suivre l'examen. Essayez des tueries répétées et capturez le succès, l'échec ou réessayez. L'épreuve de copie est facultative.",
  ["shared.previewsamples.readable_killing_blows_are_confirmed_locally_named.83de2e"] = "Des coups mortels lisibles sont confirmés localement. Le crédit honorifique peut inclure des passes décisives. Une case à cocher confirme que seule l'image a été enregistrée. L'approbation de la récompense et le paiement restent séparés; le rapport manuel est pour les détections manquées. Cette visite ne prend pas de captures d'écran.",
  ["shared.previewsamples.follow_reports_through_review_and_payment.7bf30e"] = "Suivre les rapports à travers l'examen et le paiement",
  ["shared.previewsamples.browse_hunter_and_poster_examples_awaiting_review.ee1784"] = "Parcourez les exemples de chasseur et d'affiche: en attente d'examen, approuvé, payé et rejeté. Essayez Approuver, Rejeter et Marquer payé comme exemple d'affiche.",
  ["shared.previewsamples.hunters_cannot_approve_their_own_reports_the.8e822e"] = "Les chasseurs ne peuvent pas approuver leurs propres rapports. L'afficheur examine les preuves et paie manuellement dans le jeu, puis enregistre ce paiement. Les tueries répétées peuvent compter pour un objectif de tueries multiples, sans payer deux fois pour la même récompense.",
  ["shared.previewsamples.review_enemies_suggested_by_death_reports.470074"] = "Examiner les ennemis suggérés par les rapports de décès",
  ["shared.previewsamples.inspect_sample_reports_review_a_prefilled_bounty.a7057d"] = "Inspectez des exemples de rapports, examinez une prime pré-remplie, rejetez la suggestion ou ignorez l'ennemi.",
  ["shared.previewsamples.suggestions_combine_your_deaths_and_participating_guild.4596f6"] = "Les suggestions combinent vos décès et les rapports des guildes participantes dans la fenêtre configurée. Ce sont des pistes à examiner, pas des preuves de kill vérifiées par le serveur. Rien n'est publié jusqu'à ce que vous choisissiez une audience et enregistriez.",
  ["shared.previewtest.leave_combat_before_starting_a_bounty_preview.0cf3f1"] = "Quittez le combat avant de commencer un aperçu de prime.",
